19	/// Build a logits arena from per-row logits (row `i` is token `i`'s logits).
20	fn make_arena(ctx: &DeviceContext, rows: &[Vec<f32>]) -> HiddenStates {
21	    let vocab = rows[0].len();
22	    assert!(rows.iter().all(|r| r.len() == vocab), "ragged rows");
23	    let mut hs = HiddenStates::zeros(ctx, vocab, rows.len()).unwrap();
24	    let flat: Vec<bf16> = rows
25	        .iter()
26	        .flat_map(|r| r.iter().map(|&x| bf16::from_f32(x)))
27	        .collect();
28	    ctx.stream.memcpy_htod(&flat, &mut hs.data).unwrap();
29	    ctx.sync().unwrap();
30	    hs
31	}
32	
33	fn refs(params: &[SamplingParams]) -> Vec<&SamplingParams> {
34	    params.iter().collect()
35	}
36	
37	fn greedy() -> SamplingParams {
38	    SamplingParams::default()
39	}
40	
41	fn sampling(temperature: f32, top_k: i32, top_p: f32) -> SamplingParams {
42	    SamplingParams {
43	        temperature,
44	        top_k,
45	        top_p,
46	        ..SamplingParams::default()
47	    }
48	}
49	
50	/// A one-hot-ish logits row: a single peak above a flat floor.
51	fn peak_row(vocab: usize, peak: usize, height: f32) -> Vec<f32> {
52	    let mut r = vec![0.0; vocab];
53	    r[peak] = height;
54	    r
55	}
