57	#[test]
58	fn greedy_batch_picks_each_rows_argmax() {
59	    let ctx = DeviceContext::new().unwrap();
60	    let vocab = 16;
61	    let peaks = [3usize, 7, 0, 15];
62	    let rows: Vec<Vec<f32>> = peaks.iter().map(|&p| peak_row(vocab, p, 10.0)).collect();
63	    let arena = make_arena(&ctx, &rows);
64	    let params = vec![greedy(); peaks.len()];
65	    let mut scratch = SampleScratch::new(&ctx, vocab, peaks.len()).unwrap();
66	
67	    let tokens = select_batch(
68	        &ctx,
69	        &arena,
70	        &refs(&params),
71	        &vec![0; params.len()],
72	        0,
73	        &mut scratch,
74	    )
75	    .unwrap();
76	
77	    assert_eq!(tokens, vec![3, 7, 0, 15]);
78	}
79	
80	#[test]
81	fn top_k_one_routes_through_greedy_path() {
82	    // High temperature but top_k == 1 => is_greedy() => argmax, not sampling.
83	    let ctx = DeviceContext::new().unwrap();
84	    let vocab = 16;
85	    let arena = make_arena(&ctx, &[peak_row(vocab, 5, 10.0)]);
86	    let params = vec![sampling(1.0, 1, 1.0)];
87	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
88	
89	    let tokens = select_batch(&ctx, &arena, &refs(&params), &[0], 123, &mut scratch).unwrap();
90	
91	    assert_eq!(tokens, vec![5]);
92	}
93	
94	#[test]
95	fn mixed_batch_routes_and_places_each_row() {
96	    // Row 0 greedy, row 1 sampled, row 2 greedy. Row 1's top_p (0.5) sits above
97	    // the 1/vocab argmax floor so it genuinely takes the sampler path; its dist
98	    // is near one-hot (peak prob ~1) so the nucleus is the peak and the sample
99	    // collapses there. Verifies both paths run in one call and each token lands
100	    // at its own row index.
101	    let ctx = DeviceContext::new().unwrap();
102	    let vocab = 16;
103	    let rows = vec![
104	        peak_row(vocab, 2, 12.0),
105	        peak_row(vocab, 9, 12.0),
106	        peak_row(vocab, 4, 12.0),
107	    ];
108	    let arena = make_arena(&ctx, &rows);
109	    let params = vec![greedy(), sampling(1.0, -1, 0.5), greedy()];
110	    let mut scratch = SampleScratch::new(&ctx, vocab, 3).unwrap();
111	
112	    let tokens = select_batch(&ctx, &arena, &refs(&params), &[0, 0, 0], 7, &mut scratch).unwrap();
113	
114	    assert_eq!(tokens, vec![2, 9, 4]);
115	}
116	
117	#[test]
118	fn sampling_is_seed_deterministic_and_actually_samples() {
119	    // Uniform logits: argmax would always pick index 0, so seeing >1 token over
120	    // many seeds proves the non-greedy path samples; equal seeds proves it is
121	    // reproducible. Also exercises scratch reuse across many calls.
122	    let ctx = DeviceContext::new().unwrap();
123	    let vocab = 8;
124	    let arena = make_arena(&ctx, &[vec![0.0; vocab]]);
125	    let params = vec![sampling(1.0, -1, 1.0)];
126	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
127	
128	    let a = select_batch(&ctx, &arena, &refs(&params), &[0], 42, &mut scratch).unwrap();
129	    let b = select_batch(&ctx, &arena, &refs(&params), &[0], 42, &mut scratch).unwrap();
130	    assert_eq!(a, b, "same seed must be deterministic");
131	
132	    let mut seen = HashSet::new();
133	    for s in 0..64u64 {
134	        seen.insert(select_batch(&ctx, &arena, &refs(&params), &[0], s, &mut scratch).unwrap()[0]);
135	    }
136	    assert!(
137	        seen.len() > 1,
138	        "uniform sampling should explore multiple tokens, saw {seen:?}"
139	    );
140	}
141	
142	#[test]
143	fn tiny_top_p_routes_to_argmax_even_under_bf16_ties() {
144	    // Regression for the per-step-philox migration (no per-request RNG). A tiny
145	    // top_p must collapse to the same token greedy picks. The hard case is a
146	    // bf16 tie at the top: argmax breaks it by lowest index, but the rejection
147	    // sampler would pick either tied token depending on the seed (the old
148	    // per-request seed masked this; a per-step seed exposes it). Because the
149	    // softmax max is always >= 1/vocab, top_p <= 1/vocab makes the nucleus a
150	    // single token, so the row routes to the deterministic argmax path and
151	    // matches greedy for every seed. Large vocab matches the model's
152	    // OnlineSoftmax regime.
153	    let ctx = DeviceContext::new().unwrap();
154	    let vocab = 151_936;
155	    let lo = 879usize;
156	    let hi = 6941usize;
157	    let mut row = vec![0.0f32; vocab];
158	    row[lo] = 8.0; // bf16-exact, identical to `hi` -> a true top tie
159	    row[hi] = 8.0;
160	    let arena = make_arena(&ctx, &[row]);
161	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
162	
163	    let greedy_tok = select_batch(&ctx, &arena, &[&greedy()], &[0], 0, &mut scratch).unwrap();
164	    assert_eq!(
165	        greedy_tok,
166	        vec![lo as u32],
167	        "argmax breaks the tie by lowest index"
168	    );
169	
170	    let tiny = sampling(1.0, -1, 1e-6); // 1e-6 < 1/vocab (~6.6e-6)
171	    for s in 0..64u64 {
172	        assert_eq!(
173	            select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut scratch).unwrap(),
174	            greedy_tok,
175	            "seed {s}: tiny top_p must match greedy, not sample the tied peer"
176	        );
177	    }
178	}
179	
180	#[test]
181	fn padded_arena_width_does_not_suppress_the_argmax_routing() {
182	    // qwen35 tile-aligns its logits width past the decodable vocab (#1046). A
183	    // top_p at exactly 1/decodable collapses to the argmax on the unpadded
184	    // arena, so it must still do so at twice the arena width.
185	    let ctx = DeviceContext::new().unwrap();
186	    let decodable = 256usize;
187	    let vocab = 2 * decodable;
188	    let lo = 128usize;
189	    let hi = 200usize;
190	    let mut row = vec![-1.0f32; vocab];
191	    row[lo] = 8.0; // bf16-exact, identical to `hi` -> a true top tie
192	    row[hi] = 8.0;
193	    let arena = make_arena(&ctx, &[row]);
194	
195	    let tiny = sampling(1.0, -1, 1.0 / decodable as f32);
196	
197	    // Control: at the arena width 1/256 is no longer a single-token nucleus,
198	    // and the sampler may return the tied peer.
199	    let mut wide = SampleScratch::new(&ctx, vocab, 1).unwrap();
200	    let mut sampled_the_peer = false;
201	    for s in 0..64u64 {
202	        let picked = select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut wide).unwrap()[0];
203	        assert!(picked == lo as u32 || picked == hi as u32);
204	        sampled_the_peer |= picked == hi as u32;
205	    }
206	    assert!(
207	        sampled_the_peer,
208	        "control: an arena-width routing decision puts this row on the sampler"
209	    );
210	
211	    let mut bounded = SampleScratch::with_selection_width(&ctx, vocab, decodable, 1).unwrap();
212	    for s in 0..64u64 {
213	        assert_eq!(
214	            select_batch(&ctx, &arena, &[&tiny], &[0], s, &mut bounded).unwrap(),
215	            vec![lo as u32],
216	            "seed {s}: the decodable vocab must keep this row on the argmax path"
217	        );
218	    }
219	}
220	
221	#[test]
222	fn batch_larger_than_scratch_is_rejected() {
223	    let ctx = DeviceContext::new().unwrap();
224	    let vocab = 8;
225	    let arena = make_arena(&ctx, &[peak_row(vocab, 1, 5.0), peak_row(vocab, 2, 5.0)]);
226	    let params = vec![greedy(); 2];
227	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
228	
229	    assert!(
230	        select_batch(
231	            &ctx,
232	            &arena,
233	            &refs(&params),
234	            &vec![0; params.len()],
235	            0,
236	            &mut scratch
237	        )
238	        .is_err()
239	    );
240	}
241	
242	#[test]
243	fn min_p_row_takes_the_sampler_path_and_filters() {
244	    // Two-token support: P(3) ~ 0.73, P(11) ~ 0.27. min_p = 0.5 thresholds at
245	    // 0.5 * 0.73 = 0.37, masking token 11 — every draw must return token 3.
246	    // With min_p = 0.0 the same row explores both (checked over many seeds),
247	    // proving the row genuinely rides the sampler, not argmax.
248	    let ctx = DeviceContext::new().unwrap();
249	    let vocab = 16;
250	    let mut row = vec![-60.0f32; vocab];
251	    row[3] = 1.0;
252	    row[11] = 0.0;
253	    let arena = make_arena(&ctx, &[row]);
254	    let mut scratch = SampleScratch::new(&ctx, vocab, 1).unwrap();
255	
256	    let mut filtered = sampling(1.0, -1, 1.0);
257	    filtered.min_p = 0.5;
258	    for s in 0..64u64 {
259	        assert_eq!(
260	            select_batch(&ctx, &arena, &[&filtered], &[0], s, &mut scratch).unwrap(),
261	            vec![3],
262	            "seed {s}: min_p=0.5 must mask the 0.27-prob token"
263	        );
264	    }
265	
266	    let open = sampling(1.0, -1, 1.0);
267	    let mut seen = HashSet::new();
268	    for s in 0..128u64 {
269	        seen.insert(select_batch(&ctx, &arena, &[&open], &[0], s, &mut scratch).unwrap()[0]);
270	    }
271	    assert!(
272	        seen.contains(&11),
273	        "min_p=0 should reach the 0.27-prob token across 128 seeds, saw {seen:?}"
274	    );
275	}
276	
277	#[test]
278	fn mixed_batch_keeps_plain_rows_on_the_fast_path() {
279	    // A min_p neighbor must not perturb plain sampling rows: select_batch
280	    // batches min_p rows separately, so a plain row's philox subsequence is
281	    // its index among plain rows and its tokens match a min_p-free batch
282	    // exactly. The plain rows carry top_k+top_p on a spread distribution so
283	    // the fused fast path (rejection sampling, several uniform draws) and the
284	    // min_p pipeline (renorm + one draw) genuinely diverge — riding the wrong
285	    // path shows up as different tokens, not a 1-ulp coin flip.
286	    let ctx = DeviceContext::new().unwrap();
287	    let vocab = 16;
288	    let spread: Vec<f32> = (0..vocab).map(|i| i as f32 * 0.3).collect();
289	    let rows: Vec<Vec<f32>> = vec![spread.clone(), spread.clone(), spread];
290	    let arena_mixed = make_arena(&ctx, &rows);
291	    let arena_plain = make_arena(&ctx, &rows[..2]);
292	    let mut scratch = SampleScratch::new(&ctx, vocab, rows.len()).unwrap();
293	
294	    let plain = sampling(1.0, 4, 0.9);
295	    let mut minp = sampling(1.0, 0, 1.0);
296	    minp.min_p = 0.5;
297	
298	    for seed in 0..64u64 {
299	        let mixed = select_batch(
300	            &ctx,
301	            &arena_mixed,
302	            &[&plain, &minp, &plain],
303	            &[0, 0, 0],
304	            seed,
305	            &mut scratch,
306	        )
307	        .unwrap();
308	        let alone = select_batch(
309	            &ctx,
310	            &arena_plain,
311	            &[&plain, &plain],
312	            &[0, 0],
313	            seed,
314	            &mut scratch,
315	        )
316	        .unwrap();
317	        assert_eq!(
318	            [mixed[0], mixed[2]],
319	            [alone[0], alone[1]],
320	            "seed {seed}: plain rows changed tokens because a min_p row joined the batch"
321	        );
322	    }
323	}
324	
325	/// The per-request seed contract: a seeded row's token is a pure function of
326	/// (seed, step, distribution) — independent of where the row sits in the
327	/// batch, of its neighbors, and of the engine's per-step seed.
328	#[test]
329	fn seeded_rows_replay_independent_of_batch_position() {
330	    let ctx = DeviceContext::new().unwrap();
331	    let vocab = 32_768;
332	    let flat = vec![0.0f32; vocab];
333	    let arena = make_arena(&ctx, &[flat.clone(), flat.clone(), flat]);
334	    let mut scratch = SampleScratch::new(&ctx, vocab, 3).unwrap();
335	
336	    let seeded = |seed: u64| SamplingParams {
337	        temperature: 1.0,
338	        seed: Some(seed),
339	        ..SamplingParams::default()
340	    };
341	    let unseeded = sampling(1.0, -1, 1.0);
342	
343	    // Batch A: seeded row last; batch B: seeded row first, different
344	    // neighbors and engine seed. Same request seed + step => same token.
345	    let a = select_batch(
346	        &ctx,
347	        &arena,
348	        &[&greedy(), &unseeded, &seeded(7)],
349	        &[0, 0, 5],
350	        99,
351	        &mut scratch,
352	    )
353	    .unwrap();
354	    let b = select_batch(
355	        &ctx,
356	        &arena,
357	        &[&seeded(7), &greedy()],
358	        &[5, 0],
359	        1234,
360	        &mut scratch,
361	    )
362	    .unwrap();
363	    assert_eq!(a[2], b[0], "seeded row must replay across batch layouts");
364	
365	    // Advancing the step or changing the seed moves the stream; on a flat
366	    // 32k-token distribution an accidental collision is ~3e-5.
367	    let c = select_batch(&ctx, &arena, &[&seeded(7)], &[6], 0, &mut scratch).unwrap();
368	    let d = select_batch(&ctx, &arena, &[&seeded(8)], &[5], 0, &mut scratch).unwrap();
369	    assert_ne!(a[2], c[0], "step must advance the seeded stream");
370	    assert_ne!(a[2], d[0], "seed must select a distinct stream");
371	}
372	
373	/// Latency micro-benchmark for the verify-round sampler cost (#512): span-17
374	/// rows at Qwen3 vocab, greedy argmax vs sampled paths. Not a correctness
375	/// gate — prints per-call microseconds; run with --nocapture.
376	#[test]
377	#[ignore = "GPU latency probe — run manually with --nocapture"]
378	fn select_batch_span17_latency_probe() {
379	    let ctx = DeviceContext::new().unwrap();
380	    let vocab = 151_936;
381	    let rows = 17;
382	    let logits: Vec<Vec<f32>> = (0..rows)
383	        .map(|r| {
384	            (0..vocab)
385	                .map(|v| (((v * 2_654_435_761 + r * 97) % 1000) as f32) / 50.0)
386	                .collect()
387	        })
388	        .collect();
389	    let arena = make_arena(&ctx, &logits);
390	    let mut scratch = SampleScratch::new(&ctx, vocab, rows).unwrap();
391	
392	    let cases: Vec<(&str, SamplingParams)> = vec![
393	        ("greedy", SamplingParams::default()),
394	        (
395	            "t0.8_topp0.95",
396	            SamplingParams {
397	                temperature: 0.8,
398	                top_p: 0.95,
399	                ..SamplingParams::default()
400	            },
401	        ),
402	        (
403	            "t0.7_topk20_topp0.9",
404	            SamplingParams {
405	                temperature: 0.7,
406	                top_k: 20,
407	                top_p: 0.9,
408	                ..SamplingParams::default()
409	            },
410	        ),
411	    ];
412	    for (name, p) in cases {
413	        let params = vec![p; rows];
414	        let param_refs = refs(&params);
415	        let steps = vec![0u64; rows];
416	        for _ in 0..20 {
417	            select_batch(&ctx, &arena, &param_refs, &steps, 7, &mut scratch).unwrap();
418	        }
419	        ctx.sync().unwrap();
420	        let start = std::time::Instant::now();
421	        let iters = 200;
422	        for i in 0..iters {
423	            select_batch(&ctx, &arena, &param_refs, &steps, i as u64, &mut scratch).unwrap();
424	        }
425	        ctx.sync().unwrap();
426	        let us = start.elapsed().as_micros() as f64 / iters as f64;
427	        eprintln!("select_batch span17 {name}: {us:.1} us/call");
428	    }
429	}
