79	/// Batched temperature/top-k/top-p sampling: gathers the requested bf16 arena
80	/// rows, then runs FlashInfer's batched softmax + sampling — three kernel
81	/// launches, one sync, and one D2H for the whole batch.
82	///
83	/// `seed` must be fresh per decode step (one philox seed per call; rows
84	/// decorrelate through the philox subsequence). Returns one token per row, in
85	/// `rows` order.
86	///
87	/// min_p rows run as their own pass: if they shared a call, every row would
88	/// ride the min_p kernel, whose u-scaling (`u * q`) and survivor predicate
89	/// differ from the fused fast path — a min_p == 0 row could then sample a
90	/// different token than it would alone. Partitioning here (not in callers)
91	/// keeps "min_p == 0 rows take the original path" true for every caller, at
92	/// the cost of a second full pass (gather + softmax + sample, own sync) only
93	/// when a batch actually mixes.
94	pub fn gpu_sample_batch_into(
95	    ctx: &DeviceContext,
96	    logits: HiddenStatesRef<'_>,
97	    rows: &[BatchSamplingRow],
98	    seed: u64,
99	    scratch: &mut BatchSamplingScratch,
100	) -> Result<Vec<u32>> {
101	    if rows.iter().all(|r| r.min_p > 0.0) || rows.iter().all(|r| r.min_p <= 0.0) {
102	        return sample_uniform_batch_into(ctx, logits, rows, seed, scratch);
103	    }
104	    let (minp, plain): (Vec<BatchSamplingRow>, Vec<BatchSamplingRow>) =
105	        rows.iter().copied().partition(|r| r.min_p > 0.0);
106	    let plain_tokens = sample_uniform_batch_into(ctx, logits, &plain, seed, scratch)?;
107	    // Distinct philox key for the second pass: both passes restart their
108	    // subsequences at 0, so reusing `seed` would hand minp row i the same
109	    // uniform stream as plain row i and correlate their tokens.
110	    let minp_seed = seed ^ 0x9E37_79B9_7F4A_7C15;
111	    let minp_tokens = sample_uniform_batch_into(ctx, logits, &minp, minp_seed, scratch)?;
112	    let mut plain_it = plain_tokens.into_iter();
113	    let mut minp_it = minp_tokens.into_iter();
114	    Ok(rows
115	        .iter()
116	        .map(|r| {
117	            if r.min_p > 0.0 {
118	                minp_it.next().expect("minp token per minp row")
119	            } else {
120	                plain_it.next().expect("plain token per plain row")
121	            }
122	        })
123	        .collect())
124	}
