126	/// One homogeneous FlashInfer pass (rows are all-min_p or all-plain).
127	fn sample_uniform_batch_into(
128	    ctx: &DeviceContext,
129	    logits: HiddenStatesRef<'_>,
130	    rows: &[BatchSamplingRow],
131	    seed: u64,
132	    scratch: &mut BatchSamplingScratch,
133	) -> Result<Vec<u32>> {
134	    let n = rows.len();
135	    ensure!(n > 0, "batch sampling requires at least one row");
136	    ensure!(
137	        n <= scratch.max_rows,
138	        "batch sampling scratch too small: {n} rows > capacity {}",
139	        scratch.max_rows
140	    );
141	    ensure!(
142	        logits.hidden_dim == scratch.vocab,
143	        "batch sampling vocab mismatch: logits {} vs scratch {}",
144	        logits.hidden_dim,
145	        scratch.vocab
146	    );
147	
148	    let mut row_indices = Vec::with_capacity(n);
149	    let mut temperature = Vec::with_capacity(n);
150	    let mut top_k = Vec::with_capacity(n);
151	    let mut top_p = Vec::with_capacity(n);
152	    let mut min_p = Vec::with_capacity(n);
153	    let mut has_top_k_filter = false;
154	    let mut has_top_p_filter = false;
155	    let mut has_min_p_filter = false;
156	    for r in rows {
157	        ensure!(
158	            r.row < logits.seq_len,
159	            "batch sampling row {} out of arena range {}",
160	            r.row,
161	            logits.seq_len
162	        );
163	        ensure!(
164	            r.temperature > 0.0 && r.temperature.is_finite(),
165	            "batch sampling temperature {} must be finite and > 0 (greedy rows take the argmax path)",
166	            r.temperature
167	        );
168	        ensure!(
169	            r.top_p > 0.0 && r.top_p <= 1.0,
170	            "batch sampling top_p {} must be in (0, 1]",
171	            r.top_p
172	        );
173	        ensure!(
174	            (0.0..1.0).contains(&r.min_p) && r.min_p.is_finite(),
175	            "batch sampling min_p {} must be in [0, 1)",
176	            r.min_p
177	        );
178	        row_indices.push(i32::try_from(r.row)?);
179	        temperature.push(r.temperature);
180	        // FlashInfer reads top_k as u32; "disabled" is any k >= vocab.
181	        let vocab = i32::try_from(scratch.vocab)?;
182	        let clamped_top_k = if r.top_k > 0 && r.top_k < vocab {
183	            has_top_k_filter = true;
184	            r.top_k
185	        } else {
186	            vocab
187	        };
188	        top_k.push(clamped_top_k);
189	        if r.top_p < 1.0 {
190	            has_top_p_filter = true;
191	        }
192	        top_p.push(r.top_p);
193	        if r.min_p > 0.0 {
194	            has_min_p_filter = true;
195	        }
196	        min_p.push(r.min_p);
197	    }
198	    ctx.stream
199	        .memcpy_htod(&row_indices, &mut scratch.row_indices)?;
200	    ctx.stream
201	        .memcpy_htod(&temperature, &mut scratch.temperature)?;
202	    ctx.stream.memcpy_htod(&top_k, &mut scratch.top_k)?;
203	    ctx.stream.memcpy_htod(&top_p, &mut scratch.top_p)?;
204	    if has_min_p_filter {
205	        ctx.stream.memcpy_htod(&min_p, &mut scratch.min_p)?;
206	    }
207	
208	    {
209	        let softmax_workspace_bytes = scratch.softmax_workspace.len();
210	        let (logits_ptr, _gl) = logits.data.device_ptr(&ctx.stream);
211	        let (indices_ptr, _gi) = scratch.row_indices.device_ptr(&ctx.stream);
212	        let (probs_ptr, _gp) = scratch.probs.device_ptr_mut(&ctx.stream);
213	        let (temp_ptr, _gt) = scratch.temperature.device_ptr(&ctx.stream);
214	        let (top_k_ptr, _gk) = scratch.top_k.device_ptr(&ctx.stream);
215	        let (top_p_ptr, _gtp) = scratch.top_p.device_ptr(&ctx.stream);
216	        let (min_p_ptr, _gmp) = scratch.min_p.device_ptr(&ctx.stream);
217	        // topk_row_states is only read on the min_p pipeline; the fast path
218	        // hands the kernel a null instead of borrowing the buffer.
219	        let row_states = if has_min_p_filter {
220	            Some(scratch.topk_row_states.device_ptr_mut(&ctx.stream))
221	        } else {
222	            None
223	        };
224	        let row_states_ptr = row_states.as_ref().map_or(0, |(ptr, _guard)| *ptr);
225	        let (valid_ptr, _gv) = scratch.valid.device_ptr_mut(&ctx.stream);
226	        let (out_ptr, _go) = scratch.out.device_ptr_mut(&ctx.stream);
227	        let (ws_ptr, _gw) = scratch.softmax_workspace.device_ptr_mut(&ctx.stream);
228	
229	        let err = unsafe {
230	            ffi::gpu_sample_batch_flashinfer_cuda(
231	                logits_ptr as *const ffi::Half,
232	                indices_ptr as *const i32,
233	                probs_ptr as *mut f32,
234	                temp_ptr as *const f32,
235	                top_k_ptr as *const i32,
236	                top_p_ptr as *const f32,
237	                if has_min_p_filter {
238	                    min_p_ptr as *const f32
239	                } else {
240	                    std::ptr::null()
241	                },
242	                row_states_ptr as *mut u8,
243	                valid_ptr as *mut u8,
244	                out_ptr as *mut i32,
245	                ws_ptr as *mut u8,
246	                softmax_workspace_bytes,
247	                n as i32,
248	                scratch.vocab as i32,
249	                i32::from(has_top_k_filter),
250	                i32::from(has_top_p_filter),
251	                seed,
252	                0,
253	                crate::tensor::active_cu_stream(ctx),
254	            )
255	        };
256	        ensure!(
257	            err == 0,
258	            "batch sampling kernel failed with error {err}{}",
259	            crate::ops::ffi_exception_message(err)
260	        );
261	    }
262	
263	    let out = ctx
264	        .stream
265	        .clone_dtoh(&scratch.out)
266	        .map_err(|e| anyhow!("D2H batch sample read failed: {e}"))?;
267	    let valid = ctx
268	        .stream
269	        .clone_dtoh(&scratch.valid)
270	        .map_err(|e| anyhow!("D2H batch sample valid read failed: {e}"))?;
271	    ctx.sync()?;
272	
273	    let mut tokens = Vec::with_capacity(n);
274	    for (i, r) in rows.iter().enumerate() {
275	        ensure!(
276	            valid[i] != 0,
277	            "batch sampling produced no valid token for arena row {} (probs failed to cover u)",
278	            r.row
279	        );
280	        ensure!(
281	            out[i] >= 0 && (out[i] as usize) < scratch.vocab,
282	            "batch sampling token {} for arena row {} out of vocab range {}",
283	            out[i],
284	            r.row,
285	            scratch.vocab
286	        );
287	        tokens.push(out[i] as u32);
288	    }
289	    Ok(tokens)
290	}
