292	/// Argmax — returns the index of the maximum element.
293	///
294	/// Allocates a temporary output buffer. Model decode paths use batched argmax
295	/// through `pegainfer-sample`'s `select_batch`.
296	pub fn argmax(ctx: &DeviceContext, x: &DeviceVec) -> Result<u32> {
297	    let mut out_gpu: CudaSlice<i32> = ctx
298	        .stream
299	        .alloc_zeros(1)
300	        .map_err(|e| anyhow!("Alloc failed: {}", e))?;
301	
302	    {
303	        let (x_ptr, _gx) = x.data.device_ptr(&ctx.stream);
304	        let (out_ptr, _go) = out_gpu.device_ptr_mut(&ctx.stream);
305	
306	        unsafe {
307	            ffi::argmax_cuda(
308	                x_ptr as *const ffi::Half,
309	                out_ptr as *mut i32,
310	                x.len as i32,
311	                crate::tensor::active_cu_stream(ctx),
312	            );
313	        }
314	    }
315	
316	    let result = ctx
317	        .stream
318	        .clone_dtoh(&out_gpu)
319	        .map_err(|e| anyhow!("D2H copy failed: {}", e))?;
320	    ctx.sync()?;
321	
322	    Ok(result[0] as u32)
323	}
