373	/// Partial-buffer length for the Markov-step argmax, whose tiles are 1024
374	/// elements: its read is one logits row + one bias row, so it needs 4x the
375	/// blocks of the full-row batched argmax to not be latency-bound (see
376	/// `MARKOV_STEP_TILE_ELEMS` in `argmax.cu`).
377	pub fn markov_step_argmax_partials_len(rows: usize, vocab: usize) -> usize {
378	    const TILE_ELEMS: usize = 1024;
379	    // Saturating: an overflowing request then fails every buffer-length check
380	    // downstream instead of wrapping into a small (falsely satisfiable) need.
381	    rows.saturating_mul(vocab.div_ceil(TILE_ELEMS))
382	}
