514	/// Launch the per-row logprob reduction into pre-allocated buffers laid out
515	/// `[rows]` / `[rows * k_max]` row-major; each row writes `top_k[i] <= k_max`
516	/// entries and leaves the tail untouched.
517	///
518	/// # Safety
519	///
520	/// The device-resident contents of `row_indices`, `picked`, and `top_k`
521	/// cannot be validated here: for every `i < rows`, `row_indices[i]` must lie
522	/// in `[0, logits.seq_len)`, `picked[i]` in `[0, logits.hidden_dim)`, and
523	/// `top_k[i]` in `[0, min(k_max, logits.hidden_dim)]`. The launch goes to
524	/// `active_cu_stream(ctx)`: input buffers must be populated before the
525	/// launch and outputs read back after it, in that stream's order.
526	#[allow(clippy::too_many_arguments)]
527	pub unsafe fn logprob_topk_batch_bf16_into(
528	    ctx: &DeviceContext,
529	    logits: HiddenStatesRef<'_>,
530	    row_indices: &CudaSlice<i32>,
531	    picked: &CudaSlice<i32>,
532	    top_k: &CudaSlice<i32>,
533	    rows: usize,
534	    k_max: usize,
535	    out_picked_lp: &mut CudaSlice<f32>,
536	    out_picked_rank: &mut CudaSlice<i32>,
537	    out_topk_vals: &mut CudaSlice<f32>,
538	    out_topk_ids: &mut CudaSlice<i32>,
539	) -> Result<()> {
540	    ensure!(
541	        rows > 0 && logits.hidden_dim > 0,
542	        "logprob_topk requires rows > 0 and a non-empty vocab"
543	    );
544	    let backing = logits
545	        .hidden_dim
546	        .checked_mul(logits.seq_len)
547	        .ok_or_else(|| anyhow!("logprob_topk arena extent overflows"))?;
548	    ensure!(
549	        logits.data.len() >= backing,
550	        "logprob_topk arena backing too small: have {}, need {backing}",
551	        logits.data.len()
552	    );
553	    ensure!(
554	        row_indices.len() >= rows && picked.len() >= rows && top_k.len() >= rows,
555	        "logprob_topk inputs must hold {rows} elements: have {}/{}/{}",
556	        row_indices.len(),
557	        picked.len(),
558	        top_k.len()
559	    );
560	    ensure!(
561	        out_picked_lp.len() >= rows && out_picked_rank.len() >= rows,
562	        "logprob_topk picked outputs too small: have {}/{}, need {rows}",
563	        out_picked_lp.len(),
564	        out_picked_rank.len()
565	    );
566	    let topk_needed = rows
567	        .checked_mul(k_max)
568	        .ok_or_else(|| anyhow!("logprob_topk rows * k_max overflows"))?;
569	    ensure!(
570	        out_topk_vals.len() >= topk_needed && out_topk_ids.len() >= topk_needed,
571	        "logprob_topk top-k outputs too small: have {}/{}, need {topk_needed}",
572	        out_topk_vals.len(),
573	        out_topk_ids.len()
574	    );
575	    let rows_i32 = i32::try_from(rows)?;
576	    let vocab_i32 = i32::try_from(logits.hidden_dim)?;
577	    let k_max_i32 = i32::try_from(k_max)?;
578	
579	    let (x_ptr, _gx) = logits.data.device_ptr(&ctx.stream);
580	    let (rows_ptr, _gr) = row_indices.device_ptr(&ctx.stream);
581	    let (picked_ptr, _gp) = picked.device_ptr(&ctx.stream);
582	    let (k_ptr, _gk) = top_k.device_ptr(&ctx.stream);
583	    let (lp_ptr, _gl) = out_picked_lp.device_ptr_mut(&ctx.stream);
584	    let (rank_ptr, _grank) = out_picked_rank.device_ptr_mut(&ctx.stream);
585	    let (vals_ptr, _gv) = out_topk_vals.device_ptr_mut(&ctx.stream);
586	    let (ids_ptr, _gi) = out_topk_ids.device_ptr_mut(&ctx.stream);
587	
588	    unsafe {
589	        ffi::logprob_topk_batch_bf16_cuda(
590	            x_ptr as *const ffi::Half,
591	            rows_ptr as *const i32,
592	            picked_ptr as *const i32,
593	            k_ptr as *const i32,
594	            lp_ptr as *mut f32,
595	            rank_ptr as *mut i32,
596	            vals_ptr as *mut f32,
597	            ids_ptr as *mut i32,
598	            rows_i32,
599	            vocab_i32,
600	            k_max_i32,
601	            crate::tensor::active_cu_stream(ctx),
602	        );
603	    }
604	
605	    Ok(())
606	}
