701	    out_tokens: &mut CudaSlice<u32>,
702	    sampled_tokens: &mut CudaSlice<u32>,
703	) -> Result<()> {
704	    if rows == 0 {
705	        return Err(anyhow!("markov step argmax requires at least one row"));
706	    }
707	    if base.hidden_dim == 0 {
708	        return Err(anyhow!(
709	            "markov step argmax requires a non-zero vocab (zero tiles would launch an empty grid)"
710	        ));
711	    }
712	    if step >= block_size {
713	        return Err(anyhow!(
714	            "markov step step {step} >= block_size {block_size}"
715	        ));
716	    }
717	    base.checked_extent("markov step base")?;
718	    bias.checked_extent("markov step bias")?;
719	    // The kernels derive their indices in signed int, so the products need
720	    // bounding, not just each factor.
721	    super::checked_i32(base.seq_len, "markov step base rows")?;
722	    if rows > 65_535 {
723	        return Err(anyhow!("markov step rows {rows} exceeds grid-y limit"));
724	    }
725	    if base.hidden_dim > (i32::MAX as usize) - 1024 {
726	        return Err(anyhow!("markov step vocab {} too large", base.hidden_dim));
727	    }
728	    let vocab = base.hidden_dim;
729	    if bias.hidden_dim != vocab {
730	        return Err(anyhow!(
731	            "markov step bias vocab {} != base vocab {}",
732	            bias.hidden_dim,
733	            vocab
734	        ));
735	    }
736	    if chains == 0 || !rows.is_multiple_of(chains) {
737	        return Err(anyhow!(
738	            "markov step rows {rows} not divisible by chains {chains}"
739	        ));
740	    }
741	    let base_needed = (rows / chains)
742	        .checked_mul(block_size)
743	        .ok_or_else(|| anyhow!("markov step (rows/chains)*block_size overflow"))?;
744	    if req_map.is_none() && base.seq_len < base_needed {
745	        return Err(anyhow!(
746	            "markov step base rows {} < (rows/chains)*block_size {}",
747	            base.seq_len,
748	            base_needed
749	        ));
750	    }
751	    if let Some(map) = req_map {
752	        if map.len() < rows / chains {
753	            return Err(anyhow!(
754	                "markov step req_map {} < chain groups {}",
755	                map.len(),
756	                rows / chains
757	            ));
758	        }
759	    }
760	    if bias.seq_len < rows {
761	        return Err(anyhow!("markov step bias rows {} < {}", bias.seq_len, rows));
762	    }
763	    if out_tokens.len() < rows {
764	        return Err(anyhow!(
765	            "markov step out too small: {} < {}",
766	            out_tokens.len(),
767	            rows
768	        ));
769	    }
770	    let sampled_needed = rows
771	        .checked_mul(block_size)
772	        .ok_or_else(|| anyhow!("markov step rows*block_size overflow"))?;
773	    if sampled_tokens.len() < sampled_needed {
774	        return Err(anyhow!(
775	            "markov sampled-token scratch too small: {} < {}",
776	            sampled_tokens.len(),
777	            sampled_needed
778	        ));
779	    }
780	    let needed = markov_step_argmax_partials_len(rows, vocab);
781	    if partial_values.len() < needed || partial_indices.len() < needed {
782	        return Err(anyhow!(
783	            "markov step partials too small: {}/{} need {}",
784	            partial_values.len(),
785	            partial_indices.len(),
786	            needed
787	        ));
788	    }
789	    if needed > i32::MAX as usize || sampled_needed > i32::MAX as usize {
790	        return Err(anyhow!(
791	            "markov step index space too large: partials {needed}, sampled {sampled_needed}"
792	        ));
793	    }
794	
795	    let (base_ptr, _gb) = base.data.device_ptr(&ctx.stream);
796	    let (bias_ptr, _gbi) = bias.data.device_ptr(&ctx.stream);
797	    let (pv_ptr, _gpv) = partial_values.device_ptr_mut(&ctx.stream);
798	    let (pi_ptr, _gpi) = partial_indices.device_ptr_mut(&ctx.stream);
799	    let (out_ptr, _go) = out_tokens.device_ptr_mut(&ctx.stream);
800	    let (sampled_ptr, _gs) = sampled_tokens.device_ptr_mut(&ctx.stream);
801	    let map_guard = req_map.map(|map| map.device_ptr(&ctx.stream));
802	    let map_ptr = map_guard
803	        .as_ref()
804	        .map_or(std::ptr::null(), |(ptr, _)| *ptr as *const i32);
805	
806	    let rc = unsafe {
807	        ffi::markov_step_argmax_cuda(
808	            base_ptr as *const ffi::Half,
809	            bias_ptr as *const ffi::Half,
810	            super::checked_i32(block_size, "markov step block_size")?,
811	            super::checked_i32(step, "markov step step")?,
812	            super::checked_i32(chains, "markov step chains")?,
813	            map_ptr,
814	            super::checked_i32(rows, "markov step rows")?,
815	            super::checked_i32(vocab, "markov step vocab")?,
816	            pv_ptr as *mut f32,
817	            pi_ptr as *mut i32,
818	            out_ptr as *mut u32,
819	            sampled_ptr as *mut u32,
820	            crate::tensor::active_cu_stream(ctx),
821	        )
822	    };
823	    if rc != 0 {
824	        return Err(anyhow!("markov step argmax launch failed: cuda error {rc}"));
825	    }
826	
827	    Ok(())
828	}
