855	    if rows == 0 {
856	        return Err(anyhow!("markov step top2 requires at least one row"));
857	    }
858	    if base.hidden_dim == 0 {
859	        return Err(anyhow!(
860	            "markov step top2 requires a non-zero vocab (zero tiles would launch an empty grid)"
861	        ));
862	    }
863	    if step >= block_size {
864	        return Err(anyhow!(
865	            "markov top2 step {step} >= block_size {block_size}"
866	        ));
867	    }
868	    base.checked_extent("markov top2 base")?;
869	    bias.checked_extent("markov top2 bias")?;
870	    super::checked_i32(base.seq_len, "markov top2 base rows")?;
871	    if rows > 65_535 {
872	        return Err(anyhow!("markov top2 rows {rows} exceeds grid-y limit"));
873	    }
874	    if base.hidden_dim > (i32::MAX as usize) - 1024 {
875	        return Err(anyhow!("markov top2 vocab {} too large", base.hidden_dim));
876	    }
877	    let sampled_needed = rows
878	        .checked_mul(block_size)
879	        .ok_or_else(|| anyhow!("markov top2 rows*block_size overflow"))?;
880	    if sampled_tokens.len() < sampled_needed {
881	        return Err(anyhow!(
882	            "markov top2 sampled buffer {} < rows*block_size {}",
883	            sampled_tokens.len(),
884	            sampled_needed
885	        ));
886	    }
887	    let vocab = base.hidden_dim;
888	    if bias.hidden_dim != vocab {
889	        return Err(anyhow!(
890	            "markov top2 bias vocab {} != base vocab {}",
891	            bias.hidden_dim,
892	            vocab
893	        ));
894	    }
895	    let base_needed = rows
896	        .checked_mul(block_size)
897	        .ok_or_else(|| anyhow!("markov top2 rows*block_size overflow"))?;
898	    if base.seq_len < base_needed {
899	        return Err(anyhow!(
900	            "markov top2 base rows {} < rows*block_size {}",
901	            base.seq_len,
902	            base_needed
903	        ));
904	    }
905	    if bias.seq_len < rows {
906	        return Err(anyhow!("markov top2 bias rows {} < {}", bias.seq_len, rows));
907	    }
908	    if output.len() < rows || out_top2.len() < rows {
909	        return Err(anyhow!(
910	            "markov top2 out too small: {}/{} < {}",
911	            output.len(),
912	            out_top2.len(),
913	            rows
914	        ));
915	    }
916	    let needed = markov_step_argmax_partials_len(rows, vocab);
917	    if partial_v1.len() < needed
918	        || partial_i1.len() < needed
919	        || partial_v2.len() < needed
920	        || partial_i2.len() < needed
921	    {
922	        return Err(anyhow!(
923	            "markov top2 partials too small: need {needed} per pair"
924	        ));
925	    }
926	    if needed > i32::MAX as usize || sampled_needed > i32::MAX as usize {
927	        return Err(anyhow!(
928	            "markov top2 index space too large: partials {needed}, sampled {sampled_needed}"
929	        ));
930	    }
931	
932	    let (base_ptr, _gb) = base.data.device_ptr(&ctx.stream);
933	    let (bias_ptr, _gbi) = bias.data.device_ptr(&ctx.stream);
934	    let (pv1_ptr, _g1) = partial_v1.device_ptr_mut(&ctx.stream);
935	    let (pi1_ptr, _g2) = partial_i1.device_ptr_mut(&ctx.stream);
936	    let (pv2_ptr, _g3) = partial_v2.device_ptr_mut(&ctx.stream);
937	    let (pi2_ptr, _g4) = partial_i2.device_ptr_mut(&ctx.stream);
938	    let (out_ptr, _g5) = output.device_ptr_mut(&ctx.stream);
939	    let (samp_ptr, _g6) = sampled_tokens.device_ptr_mut(&ctx.stream);
940	    let (o2_ptr, _g7) = out_top2.device_ptr_mut(&ctx.stream);
