948	    let vocab_i = super::checked_i32(vocab, "markov top2 vocab")?;
949	    let rc = unsafe {
950	        ffi::markov_step_top2_cuda(
951	            base_ptr as *const ffi::Half,
952	            bias_ptr as *const ffi::Half,
953	            block_i,
954	            step_i,
955	            chains_i,
956	            rows_i,
957	            vocab_i,
958	            pv1_ptr as *mut f32,
959	            pi1_ptr as *mut i32,
960	            pv2_ptr as *mut f32,
961	            pi2_ptr as *mut i32,
962	            out_ptr as *mut u32,
963	            samp_ptr as *mut u32,
964	            o2_ptr as *mut u32,
965	            crate::tensor::active_cu_stream(ctx),
