975	/// Hedge-ladder branch force (see `hedge_ladder_force_cuda`): stamps chain
976	/// `(i, j)`'s device-resident runner token into the prev buffer and the
977	/// sampled block at `step`, for all `n` requests.
978	#[allow(clippy::too_many_arguments)]
979	///
980	/// # Safety
981	///
982	/// `req_map` lives on device and cannot be validated here: every
983	/// `req_map[0..n]` value must be in `0..runner_stride`, or the runner gather
984	/// reads out of bounds on the GPU. Validate on the host before uploading.
985	pub unsafe fn hedge_ladder_force_into(
986	    ctx: &DeviceContext,
987	    prev_tokens: &mut CudaSlice<u32>,
988	    sampled_tokens: &mut CudaSlice<u32>,
989	    runner_tokens: &CudaSlice<u32>,
990	    req_map: &CudaSlice<i32>,
991	    n: usize,
992	    c: usize,
993	    j: usize,
994	    runner_stride: usize,
995	    block_size: usize,
996	    step: usize,
997	) -> Result<()> {
998	    if n == 0 || c == 0 || j >= c {
999	        return Err(anyhow!("hedge force bad shape: n={n} c={c} j={j}"));
1000	    }
1001	    let rows = n
1002	        .checked_mul(c)
1003	        .ok_or_else(|| anyhow!("hedge force n*c overflow"))?;
1004	    let sampled_needed = rows
1005	        .checked_mul(block_size)
1006	        .ok_or_else(|| anyhow!("hedge force n*c*block_size overflow"))?;
1007	    // Mapped indices may address anywhere in `0..runner_stride`, so the WHOLE
1008	    // stripe must be backed, not just its first `n` entries.
1009	    let runner_needed = j
1010	        .checked_add(1)
1011	        .and_then(|v| v.checked_mul(runner_stride))
1012	        .ok_or_else(|| anyhow!("hedge force runner stripe overflow"))?;
1013	    if prev_tokens.len() < rows
1014	        || sampled_tokens.len() < sampled_needed
1015	        || runner_tokens.len() < runner_needed
1016	    {
1017	        return Err(anyhow!("hedge force buffers too small"));
1018	    }
1019	    if step >= block_size {
1020	        return Err(anyhow!(
1021	            "hedge force step {step} >= block_size {block_size}"
1022	        ));
1023	    }
1024	    if runner_stride < n {
1025	        return Err(anyhow!("hedge force runner stride {runner_stride} < n {n}"));
1026	    }
1027	    if req_map.len() < n {
1028	        return Err(anyhow!("hedge force req_map {} < n {n}", req_map.len()));
1029	    }
1030	    if n > (i32::MAX as usize) - 128 {
1031	        return Err(anyhow!("hedge force n {n} too large"));
1032	    }
1033	    if sampled_needed > i32::MAX as usize || runner_needed > i32::MAX as usize {
1034	        return Err(anyhow!(
1035	            "hedge force index space too large: sampled {sampled_needed}, runner {runner_needed}"
1036	        ));
1037	    }
1038	    let n_i = super::checked_i32(n, "hedge force n")?;
1039	    let c_i = super::checked_i32(c, "hedge force c")?;
1040	    let j_i = super::checked_i32(j, "hedge force j")?;
1041	    let stride_i = super::checked_i32(runner_stride, "hedge force runner_stride")?;
1042	    let block_i = super::checked_i32(block_size, "hedge force block_size")?;
1043	    let step_i = super::checked_i32(step, "hedge force step")?;
1044	    let (prev_ptr, _g1) = prev_tokens.device_ptr_mut(&ctx.stream);
1045	    let (samp_ptr, _g2) = sampled_tokens.device_ptr_mut(&ctx.stream);
1046	    let (run_ptr, _g3) = runner_tokens.device_ptr(&ctx.stream);
1047	    let (map_ptr, _g4) = req_map.device_ptr(&ctx.stream);
1048	    let rc = unsafe {
1049	        ffi::hedge_ladder_force_cuda(
1050	            prev_ptr as *mut u32,
1051	            samp_ptr as *mut u32,
1052	            run_ptr as *const u32,
1053	            map_ptr as *const i32,
1054	            n_i,
1055	            c_i,
1056	            j_i,
1057	            stride_i,
1058	            block_i,
1059	            step_i,
1060	            crate::tensor::active_cu_stream(ctx),
1061	        )
1062	    };
1063	    if rc != 0 {
1064	        return Err(anyhow!("hedge ladder force launch failed: cuda error {rc}"));
1065	    }
1066	    Ok(())
1067	}
