14	/// One non-greedy row of a batched sampling call.
15	///
16	/// `temperature` must be > 0 and `top_p` in (0, 1] — greedy rows
17	/// (`temperature <= 0` or `top_k == 1`) belong on the argmax path.
18	/// `top_k <= 0` means disabled. `min_p` in [0, 1); `0.0` means disabled —
19	/// `gpu_sample_batch_into` partitions min_p rows into their own pass, so
20	/// callers may mix freely.
21	#[derive(Clone, Copy, Debug)]
22	pub struct BatchSamplingRow {
23	    /// Row index into the logits arena.
24	    pub row: usize,
25	    pub temperature: f32,
26	    pub top_k: i32,
