47	impl BatchSamplingScratch {
48	    pub fn new(ctx: &DeviceContext, max_rows: usize, vocab: usize) -> Result<Self> {
49	        ensure!(
50	            max_rows > 0 && vocab > 0,
51	            "batch sampling scratch requires max_rows > 0 and vocab > 0"
52	        );
53	        // OnlineSoftmax vocab-splitting path: batch x ceil(vocab / 8192)
54	        // partials of {f32 max, f32 denominator}, plus alignment slack.
55	        let softmax_workspace_bytes = max_rows * vocab.div_ceil(8192) * 8 + 256;
56	        let topk_row_states_bytes = unsafe { ffi::gpu_sample_topk_renorm_row_states_bytes_cuda() };
57	        let alloc = |n: usize| -> Result<CudaSlice<f32>> {
58	            ctx.stream
59	                .alloc_zeros(n)
60	                .map_err(|e| anyhow!("batch sampling scratch alloc failed: {e}"))
61	        };
62	        Ok(Self {
63	            probs: alloc(max_rows * vocab)?,
64	            row_indices: ctx.stream.alloc_zeros(max_rows)?,
65	            temperature: alloc(max_rows)?,
66	            top_k: ctx.stream.alloc_zeros(max_rows)?,
67	            top_p: alloc(max_rows)?,
68	            min_p: alloc(max_rows)?,
69	            topk_row_states: ctx.stream.alloc_zeros(topk_row_states_bytes)?,
70	            valid: ctx.stream.alloc_zeros(max_rows)?,
71	            out: ctx.stream.alloc_zeros(max_rows)?,
72	            softmax_workspace: ctx.stream.alloc_zeros(softmax_workspace_bytes)?,
73	            max_rows,
74	            vocab,
75	        })
76	    }
