384	/// Row-wise two-stage bf16 argmax over `rows` rows of `n`: tile-parallel
385	/// partials then one finalize block per row. Same per-row total order as the
386	/// retired single-row `argmax_bf16_into` (lowest GLOBAL index wins ties, NaN
387	/// never wins) — the
388	/// partials carry global indices, so each row's result is bit-identical to
389	/// the single-block scan (and independent of the other rows) while each vocab
390	/// row spreads over ~n/4096 CTAs instead of one. `partial_*` must hold
391	/// `argmax_batch_bf16_split_partials_len(rows, n)` elements; `values`/`indices`
392	/// hold one element per row.
393	#[allow(clippy::too_many_arguments)]
394	pub fn argmax_bf16_split_into(
395	    ctx: &DeviceContext,
396	    logits: &CudaSlice<half::bf16>,
397	    rows: usize,
398	    n: usize,
399	    partial_values: &mut CudaSlice<f32>,
400	    partial_indices: &mut CudaSlice<i32>,
401	    values: &mut CudaSlice<half::bf16>,
402	    indices: &mut CudaSlice<i32>,
403	) -> Result<()> {
404	    if rows == 0 || n == 0 || logits.len() < rows * n {
405	        return Err(anyhow!(
406	            "argmax_bf16_split_into logits too small: have {}, need {}",
407	            logits.len(),
408	            rows * n
409	        ));
410	    }
411	    if values.len() < rows || indices.len() < rows {
412	        return Err(anyhow!(
413	            "argmax_bf16_split_into outputs must hold {rows} elements: have {}/{}",
414	            values.len(),
415	            indices.len()
416	        ));
417	    }
418	    let needed = argmax_batch_bf16_split_partials_len(rows, n);
419	    if partial_values.len() < needed || partial_indices.len() < needed {
420	        return Err(anyhow!(
421	            "argmax_bf16_split_into partials too small: {}/{} need {needed}",
422	            partial_values.len(),
423	            partial_indices.len()
424	        ));
425	    }
426	    let (x_ptr, _gx) = logits.device_ptr(&ctx.stream);
427	    let (pv_ptr, _gpv) = partial_values.device_ptr_mut(&ctx.stream);
428	    let (pi_ptr, _gpi) = partial_indices.device_ptr_mut(&ctx.stream);
429	    let (v_ptr, _gv) = values.device_ptr_mut(&ctx.stream);
430	    let (i_ptr, _gi) = indices.device_ptr_mut(&ctx.stream);
431	    unsafe {
432	        ffi::argmax_batch_bf16_split_cuda(
433	            x_ptr as *const ffi::Half,
434	            v_ptr as *mut ffi::Half,
435	            i_ptr as *mut i32,
436	            pv_ptr as *mut f32,
437	            pi_ptr as *mut i32,
438	            rows as i32,
439	            n as i32,
440	            crate::tensor::active_cu_stream(ctx),
441	        );
442	    }
443	    Ok(())
444	}
