58	// top-p renorm, then FlashInfer's MinPSamplingFromProb with the per-row
59	// thresholds. min_p_arr == nullptr keeps the original fused single-kernel
60	// paths bit-for-bit (the fast path).
61	//
62	// Per-request seeds deliberately do NOT go through FlashInfer's `seed_arr`:
63	// these kernels read `seed_arr[0]` (one seed for the whole batch) and fold
64	// `blockIdx.x` into the philox subsequence, so a request's stream would
65	// change with its position in the batch. Seeded rows are instead sampled as
66	// their own n_rows=1 calls by the Rust layer, with the request seed and step
67	// mixed into `seed` — blockIdx is then always 0 and replay is independent of
68	// batch composition.
69	extern "C" int gpu_sample_batch_flashinfer_cuda(
70	    const __nv_bfloat16* logits, const int* row_indices, float* probs_scratch,
71	    const float* temperature_arr, const int* top_k_arr, const float* top_p_arr,
72	    const float* min_p_arr, uint8_t* topk_row_states_scratch,
73	    uint8_t* valid_scratch, int* output, void* softmax_workspace,
74	    size_t softmax_workspace_bytes, int n_rows, int vocab_size, int has_top_k_filter,
75	    int has_top_p_filter, uint64_t seed, uint64_t offset, cudaStream_t stream) {
76	  PEGAINFER_FFI_GUARD_BEGIN
77	  dim3 gather_grid(
78	      (vocab_size + GATHER_CAST_BLOCK * GATHER_CAST_ELEMS_PER_THREAD - 1) /
79	          (GATHER_CAST_BLOCK * GATHER_CAST_ELEMS_PER_THREAD),
80	      n_rows);
81	  gather_cast_logits_f32_kernel<<<gather_grid, GATHER_CAST_BLOCK, 0, stream>>>(
82	      logits, row_indices, probs_scratch, vocab_size);
83	  cudaError_t err = cudaGetLastError();
84	  if (err != cudaSuccess) {
85	    return static_cast<int>(err);
86	  }
87	
88	  // In-place: phase 2 of both OnlineSoftmax strategies is an elementwise
89	  // read-then-write of the same index.
90	  err = flashinfer::sampling::OnlineSoftmax<float>(
91	      probs_scratch, probs_scratch, n_rows, vocab_size, const_cast<float*>(temperature_arr),
92	      /*temperature_val=*/1.0f, softmax_workspace, softmax_workspace_bytes,
93	      /*enable_pdl=*/false, stream);
