95	    return static_cast<int>(err);
96	  }
97	
98	  bool* valid = reinterpret_cast<bool*>(valid_scratch);
99	  if (min_p_arr != nullptr) {
100	    if (has_top_k_filter) {
101	      auto* row_states =
102	          reinterpret_cast<flashinfer::sampling::RadixRowState*>(topk_row_states_scratch);
103	      if (row_states == nullptr) {
104	        return static_cast<int>(cudaErrorInvalidValue);
105	      }
106	      // In-place: the renorm kernels reduce a threshold first, then rewrite
107	      // each element from its own index.
108	      err = flashinfer::sampling::RadixTopKRenormProbMultiCTA<float, int>(
109	          probs_scratch, probs_scratch, const_cast<int*>(top_k_arr), n_rows,
110	          /*top_k_val=*/0, vocab_size, row_states, /*deterministic=*/false, stream);
111	      if (err != cudaSuccess) {
112	        return static_cast<int>(err);
113	      }
114	    }
115	    if (has_top_p_filter) {
116	      err = flashinfer::sampling::TopPRenormProb<float>(
117	          probs_scratch, probs_scratch, const_cast<float*>(top_p_arr), n_rows,
118	          /*top_p_val=*/0.0f, vocab_size, stream);
119	      if (err != cudaSuccess) {
